<script setup>import {ref} from 'vue';import {Head} from '@inertiajs/vue3';import {postJSON} from '../lib/http';import Badge from '../Components/Badge.vue';import {statuses,date} from '../lib/labels';const reference=ref(''),secret=ref(''),result=ref(null),error=ref(''),busy=ref(false),comment=ref(''),notice=ref('');async function search(){error.value='';busy.value=true;result.value=null;try{result.value=await postJSON('/suivi/rechercher',{reference:reference.value,secret:secret.value});}catch(e){error.value=e.message}finally{busy.value=false}}async function act(working){error.value='';try{await postJSON('/suivi/retour',{reference:reference.value,secret:secret.value,comment:comment.value,...(working===undefined?{}:{working})});comment.value='';await search();notice.value='Votre retour a été enregistré.';}catch(e){error.value=e.message}}</script><template><Head title="Suivre mon signalement"/><section class="narrow track-experience"><div class="page-heading"><span class="eyebrow">CHAQUE ÉTAPE RESTE VISIBLE</span><h1>Où en est la réparation ?</h1><p>Munissez-vous de votre référence et de votre code secret.</p></div><form class="card form-stack" @submit.prevent="search"><label>Référence<input v-model="reference" required placeholder="EAU-..."></label><label>Code secret<input v-model="secret" required type="password" autocomplete="off"></label><button class="btn btn-primary" :disabled="busy">{{busy?'Recherche…':'Consulter le suivi'}}</button></form><div v-if="error" class="notice error">{{error}}</div><div v-if="notice" class="notice success">{{notice}}</div><div v-if="result" class="card form-stack mt"><span class="eyebrow">{{result.reference}}</span><h2>{{result.point}}</h2><Badge :value="result.status"/><ol class="timeline"><li v-for="(h,i) in result.history" :key="i"><strong>{{statuses[h.to_status]}}</strong><small>{{date(h.created_at)}}</small></li></ol><label>Ajouter une précision ou votre retour<textarea v-model="comment" minlength="5" maxlength="2000" rows="3"></textarea></label><div v-if="result.status==='repare'" class="button-row"><button class="btn btn-primary" :disabled="comment.length<5" @click="act(true)">L’eau est revenue</button><button class="btn btn-outline" :disabled="comment.length<5" @click="act(false)">Le problème persiste</button></div><button v-else class="btn btn-outline" :disabled="comment.length<5" @click="act()">Envoyer la précision</button></div></section></template>
